import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

public class SolutionTest {
    public static void main(String[] args) throws Exception {
        expectIAE(() -> Solution.isHeld(null, "k"));
        expectIAE(() -> Solution.isHeld("", "k"));
        expectIAE(() -> Solution.holdCount("g", null));
        expectIAE(() -> Solution.release("g", ""));
        expectAcquireIAE("", "k");

        Solution.clearUnused();
        Solution.acquire("g", "k");
        Solution.acquire("g", "k");
        check(Solution.isHeld("g", "k"), "lock should be held");
        check(Solution.holdCount("g", "k") == 2, "reentrant count");
        check(!Solution.isHeld("other", "k"), "different group shared lock");

        AtomicReference<Throwable> nonOwnerResult = new AtomicReference<>();
        Thread nonOwner = new Thread(() -> {
            try {
                Solution.release("g", "k");
                nonOwnerResult.set(new AssertionError("non-owner release succeeded"));
            } catch (Throwable t) {
                nonOwnerResult.set(t);
            }
        });
        nonOwner.start();
        nonOwner.join();
        check(nonOwnerResult.get() instanceof IllegalMonitorStateException, "non-owner exception");
        check(Solution.holdCount("g", "k") == 2, "non-owner changed count");

        Solution.clearUnused();
        check(Solution.holdCount("g", "k") == 2, "clearUnused removed held lock");

        CountDownLatch attempting = new CountDownLatch(1);
        AtomicBoolean acquired = new AtomicBoolean();
        AtomicReference<Throwable> waiterProblem = new AtomicReference<>();
        Thread waiter = new Thread(() -> {
            attempting.countDown();
            try {
                Solution.acquire("g", "k");
                acquired.set(true);
                Solution.release("g", "k");
            } catch (Throwable t) {
                waiterProblem.set(t);
            }
        });
        waiter.start();
        check(attempting.await(1, TimeUnit.SECONDS), "waiter did not start");
        Thread.sleep(100);
        check(!acquired.get(), "waiter acquired held lock");
        Solution.release("g", "k");
        check(Solution.holdCount("g", "k") == 1, "partial release count");
        Thread.sleep(50);
        check(!acquired.get(), "lock released before count reached zero");
        Solution.release("g", "k");
        waiter.join(2000);
        check(!waiter.isAlive(), "waiter remained blocked");
        check(waiterProblem.get() == null, "waiter failed: " + waiterProblem.get());
        check(acquired.get(), "waiter never acquired");
        check(!Solution.isHeld("g", "k") && Solution.holdCount("g", "k") == 0, "released state");

        Solution.acquire("interrupt", "key");
        CountDownLatch interruptAttempt = new CountDownLatch(1);
        AtomicBoolean interrupted = new AtomicBoolean();
        Thread interruptible = new Thread(() -> {
            interruptAttempt.countDown();
            try {
                Solution.acquire("interrupt", "key");
            } catch (InterruptedException expected) {
                interrupted.set(true);
            }
        });
        interruptible.start();
        interruptAttempt.await();
        Thread.sleep(100);
        interruptible.interrupt();
        interruptible.join(2000);
        check(interrupted.get(), "acquire was not interruptible");
        check(Solution.holdCount("interrupt", "key") == 1, "interruption changed owner count");
        Solution.release("interrupt", "key");

        Solution.acquire("space", "key");
        AtomicBoolean distinctAcquired = new AtomicBoolean();
        Thread distinct = new Thread(() -> {
            try {
                Solution.acquire(" space", "key");
                distinctAcquired.set(true);
                Solution.release(" space", "key");
            } catch (InterruptedException e) {
                throw new AssertionError(e);
            }
        });
        distinct.start();
        distinct.join(2000);
        check(distinctAcquired.get(), "whitespace-significant group was not independent");
        Solution.release("space", "key");

        expectThrows(IllegalMonitorStateException.class, () -> Solution.release("absent", "key"));
        Solution.clearUnused();
    }

    private static void expectAcquireIAE(String group, String key) {
        try {
            Solution.acquire(group, key);
            throw new AssertionError("expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        } catch (InterruptedException e) {
            throw new AssertionError(e);
        }
    }

    private static void expectIAE(Runnable action) {
        expectThrows(IllegalArgumentException.class, action);
    }

    private static void expectThrows(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable t) {
            if (type.isInstance(t)) return;
            throw new AssertionError("wrong exception", t);
        }
        throw new AssertionError("expected " + type.getSimpleName());
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }
}

